package com.aetherforge.api;import com.aetherforge.service.KnowledgeService;import org.springframework.web.bind.annotation.*;import org.springframework.web.multipart.MultipartFile;import java.util.*;
@RestController @RequestMapping("/api/v1/documents") public class KnowledgeController {private final KnowledgeService k;public KnowledgeController(KnowledgeService k){this.k=k;}@GetMapping List<Map<String,Object>> docs(){return k.docs();}@GetMapping("/search") List<Map<String,Object>> search(@RequestParam String q){return k.search(q);}@PostMapping(consumes="multipart/form-data") Map<String,Object> upload(@RequestPart MultipartFile file)throws Exception{k.upload("00000000-0000-0000-0000-000000000001",file);return Map.of("ok",true,"mode","RAG/LEXICAL");}}
